mapper.update:
UPDATE biz_cloak
SET status = 0,
    updated_by = #{updatedBy}
WHERE batch_id = #{batchId}
    AND status IN (2, 3)
    AND deleted_at = 0

UPDATE biz_cloak
SET status = #{status},
    updated_by = #{updatedBy}
WHERE batch_id = #{batchId}
    AND deleted_at = 0

mapper.sql:
WHERE status = 1 AND deleted_at = 0
AND ( project_name LIKE CONCAT('%', #{keyword}, '%') OR really_url LIKE CONCAT('%', #{keyword}, '%') OR promotion_url LIKE CONCAT('%', #{keyword}, '%') )
AND project_id = #{projectId}
AND country = #{country}
AND created_at >= CONCAT(#{startDate}, ' 00:00:00')
AND created_at < DATE_ADD(CONCAT(#{endDate}, ' 00:00:00'), INTERVAL 1 DAY)

mapper.select:
SELECT * FROM biz_cloak WHERE status = 1 AND deleted_at = 0 AND id IN
#{id}
ORDER BY id

SELECT DISTINCT cloak.agency_line_id FROM biz_cloak cloak INNER JOIN biz_cloak_batch batch ON batch.id = cloak.batch_id AND batch.deleted_at = 0 WHERE cloak.status = 1 AND cloak.deleted_at = 0 AND cloak.agency_line_id IN
#{agencyLineId}
AND batch.request_id != #{requestId}
ORDER BY cloak.agency_line_id
